pub(crate) fn find(key: &str) -> Option<&'static str> {
    if key >= "ψευσθησομενοσ" {
        return m15(key);
    }
    if key >= "τεταμιευμενοσ" {
        return m14(key);
    }
    if key >= "πιθων" {
        return m13(key);
    }
    if key >= "ονηθεισ" {
        return m12(key);
    }
    if key >= "λελογχευμενοσ" {
        return m11(key);
    }
    if key >= "θρυψασ" {
        return m10(key);
    }
    if key >= "ερηριπωσ" {
        return m9(key);
    }
    if key >= "επικαταλυων" {
        return m8(key);
    }
    if key >= "εξερασων" {
        return m7(key);
    }
    if key >= "εμπιπτων" {
        return m6(key);
    }
    if key >= "εκκεκλασμενοσ" {
        return m5(key);
    }
    if key >= "δηιων" {
        return m4(key);
    }
    if key >= "αποτραπων" {
        return m3(key);
    }
    if key >= "αξων" {
        return m2(key);
    }
    if key >= "ανακρουσαμενοσ" {
        return m1(key);
    }
    m0(key)
}

